# Build a golden test set of 8 HR-policy Q&A scenarios. Each case has an input (employee question), a reference answer, and metadata (category, difficulty).

# %%
from dataclasses import dataclass, field
from typing import Optional
import hashlib
import time
import json

@dataclass
class TestCase:
    input_text: str
    reference_output: Optional[str] = None
    category: str = "general"
    tags: list = field(default_factory=list)
    id: str = ""

    def __post_init__(self):
        if not self.id:
            self.id = hashlib.md5(self.input_text.encode()).hexdigest()[:8]

@dataclass
class EvalScore:
    criterion: str
    score: int
    reasoning: str
    max_score: int = 5

@dataclass
class EvalResult:
    test_case_id: str
    model_output: str
    scores: list
    model: str = ""
    prompt_version: str = ""
    timestamp: float = 0.0

    def __post_init__(self):
        if not self.timestamp:
            self.timestamp = time.time()

    def average_score(self):
        if not self.scores:
            return 0.0
        return sum(s.score for s in self.scores) / len(self.scores)

