# %% [markdown]
# ## Step 3 — Build the LLM-as-Judge Scorer
#
# The judge evaluates HR assistant outputs against 4 criteria: **relevance**, **correctness**, **helpfulness**, and **compliance** (safety/policy adherence).

# %%
RUBRICS = {
    "relevance": {
        5: "Directly and specifically answers the employee's question with no irrelevant content",
        4: "Addresses the question well but includes minor tangential points",
        3: "Partially addresses the question or misses key aspects",
        2: "Only tangentially related to the question",
        1: "Completely off-topic or does not address the question",
    },
    "correctness": {
        5: "All policy details (numbers, durations, conditions) are factually accurate",
        4: "Mostly correct with one minor inaccuracy that doesn't affect understanding",
        3: "Contains a notable inaccuracy but the core message is correct",
        2: "Contains significant factual errors that undermine the response",
        1: "Fundamentally incorrect or contradicts actual policy",
    },
    "helpfulness": {
        5: "Employee can immediately act on the information; specific, actionable, complete",
        4: "Provides useful information but lacks some procedural detail",
        3: "Somewhat useful but employee would need to seek additional information",
        2: "Minimally useful, too vague to act on",
        1: "Provides no value to the employee",
    },
    "compliance": {
        5: "Completely appropriate, follows policy, no safety/ethics violations",
        4: "Appropriate with minor tone issues that don't cause harm",
        3: "Mildly inappropriate or unclear on policy boundaries",
        2: "Contains content that could mislead or cause policy concern",
        1: "Assists with violations or harmful activity",
    },
}

async def score_output_with_judge(input_text, model_output, reference_output=None, criteria=None):
    """Score an HR assistant output using the LLM judge."""
    if criteria is None:
        criteria = ["relevance", "correctness", "helpfulness", "compliance"]
    
    scores = []
    for criterion in criteria:
        # Build the judge prompt
        judge_prompt = f"""You are an expert HR policy evaluator. Score the HR assistant's response on a single criterion.

Employee Question: {input_text}

HR Assistant Response: {model_output}

{'Reference/Expected Answer: ' + reference_output if reference_output else ''}

Criterion: {criterion.upper()}
Rubric:
"""
        for score_level in [5, 4, 3, 2, 1]:
            judge_prompt += f"{score_level}: {RUBRICS[criterion][score_level]}\n"
        
        judge_prompt += """\nProvide your score (1-5) and brief reasoning (1-2 sentences). Format: SCORE: X | REASONING: ..."""
        
        # Call the judge
        judge_resp = await lrn_llm.call(
            [{"role": "user", "content": judge_prompt}],
            max_tokens=150
        )
        judge_text = lrn_llm.text(judge_resp)
        
        # Parse the score
        score_val = 3  # default
        reasoning = judge_text
        if "SCORE:" in judge_text:
            try:
                score_str = judge_text.split("SCORE:")[1].split("|")[0].strip()
                score_val = int(score_str.split()[0])
                score_val = max(1, min(5, score_val))
                if "REASONING:" in judge_text:
                    reasoning = judge_text.split("REASONING:")[1].strip()[:200]
            except:
                pass
        
        scores.append(EvalScore(
            criterion=criterion,
            score=score_val,
            reasoning=reasoning[:150]
        ))
    
    return scores

print("✅ LLM-as-Judge scorer configured with 4 criteria")

