# %% [markdown]
# ## Step 7 — Bootstrap Confidence Intervals
#
# Compute confidence intervals for each criterion, accounting for sampling uncertainty. This is how we determine if v2 is statistically better than v1.

# %%
import statistics

def bootstrap_confidence_interval(scores, n_bootstrap=500, confidence=0.95):
    """Estimate CI by resampling the score distribution."""
    if len(scores) < 2:
        return (0.0, 0.0, 0.0)
    n = len(scores)
    means = []
    seed_base = int(sum(scores) * 1000) % (2**31 - 1)
    for i in range(n_bootstrap):
        seed = (seed_base + i * 7919) % (2**31 - 1)
        sample = []
        for j in range(n):
            idx = (seed + j * 31) % n
            sample.append(scores[idx])
            seed = (seed * 1103515245 + 12345) % (2**31 - 1)
        means.append(sum(sample) / len(sample))
    means.sort()
    alpha = (1 - confidence) / 2
    lower_idx = max(0, int(alpha * n_bootstrap))
    upper_idx = min(len(means) - 1, int((1 - alpha) * n_bootstrap))
    mean = sum(scores) / len(scores)
    return (round(means[lower_idx], 3), round(mean, 3), round(means[upper_idx], 3))

# Compute per-criterion CIs for both versions
print("="*70)
print("  CONFIDENCE INTERVALS (95%)")
print("="*70)

criteria = ["relevance", "correctness", "helpfulness", "compliance"]
for criterion in criteria:
    v1_scores = [s.score for r in v1_results for s in r.scores if s.criterion == criterion]
    v2_scores = [s.score for r in v2_results for s in r.scores if s.criterion == criterion]
    
    if v1_scores and v2_scores:
        v1_ci = bootstrap_confidence_interval(v1_scores)
        v2_ci = bootstrap_confidence_interval(v2_scores)
        v1_mean = sum(v1_scores) / len(v1_scores)
        v2_mean = sum(v2_scores) / len(v2_scores)
        diff = v2_mean - v1_mean
        
        print(f"\n{criterion.upper()}")
        print(f"  v1: {v1_mean:.3f} (95% CI: [{v1_ci[0]:.3f}, {v1_ci[2]:.3f}])")
        print(f"  v2: {v2_mean:.3f} (95% CI: [{v2_ci[0]:.3f}, {v2_ci[2]:.3f}])")
        print(f"  Diff (v2 - v1): {diff:+.3f}")
        
        # Simple significance test: CIs don't overlap
        if v2_ci[0] > v1_ci[2]:
            print(f"  Status: ✅ IMPROVEMENT (statistically significant)")
        elif v2_ci[2] < v1_ci[0]:
            print(f"  Status: ❌ REGRESSION (statistically significant)")
        else:
            print(f"  Status: ➜ STABLE (no significant difference)")

print("\n" + "="*70)

