v1_overall_mean = sum(all_v1_scores) / len(all_v1_scores) if all_v1_scores else 0
v2_overall_mean = sum(all_v2_scores) / len(all_v2_scores) if all_v2_scores else 0
overall_diff = v2_overall_mean - v1_overall_mean

v1_ci = bootstrap_confidence_interval(all_v1_scores)
v2_ci = bootstrap_confidence_interval(all_v2_scores)

